<script setup lang="ts">
import CloudSyncWidget from './components/CloudSyncWidget.vue'
import NewBadge from './components/NewBadge.vue'
import TitleSelfBuffAnim from './components/TitleSelfBuffAnim.vue'
import { isBeta } from './utils/betaSettings';
import { useRouter } from 'vue-router'
import { computed } from 'vue'
import { useSetting } from './store/settingsStore'

const icon = (document.getElementById('app-icon') as HTMLLinkElement | null)?.href ?? ''
const beta = isBeta()
const router = useRouter()

const titles: [string, number, number?][] = [
    ["TFF's Exedra Toolbox", 50, 34],
    ["TFF's Mess of a Toolbox", 47, 34],
    ["TFF's Ever Changing Beta Toolbox", 0, 20],
    ["TFF is not a whale!", 0, 1],
    ["[img:haru.webp] is the biggest whale!", 0, 1],
    ["[img:haru2.webp]", 0, 1],
    ["Time to [img:hyperwhale.webp]", 0, 1],
    ["[img:feliwhale.webp]", 0, 1],
    ["[img:whale.svg]", 0, 1],
    ["[img:ren.webp]", 0, 1],
    ["[img:nya.webp]", 1],
    ["[img:rika_bonked.webp][img:lys_bonking.webp]", 0, 1],
    ["[img:lys_bonked.webp][img:rika_bonking.webp]", 0, 1],
    ["[img:rika.webp]", 1],
    ["[anim:selfbuff.webp]", 1],
]

function pickWeightedTitle(titles: [string, number, number?][]): string {
    const weights = titles.map(([title, normalWeight, betaWeight]) => ({
        title,
        weight: beta ? (betaWeight ?? normalWeight) : normalWeight,
    }))

    const totalWeight = weights.reduce((sum, { weight }) => sum + weight, 0)
    let random = Math.random() * totalWeight

    for (const { title, weight } of weights) {
        random -= weight
        if (random < 0) {
            return title
        }
    }

    return weights[0].title
}

const title = pickWeightedTitle(titles)

type TitlePart = { type: 'text'; value: string } | { type: 'img' | 'anim'; src: string }

const IMG_BASE = '/exedra-dmg-calc/header_images/'

function resolveImgSrc(path: string): string {
    if (path.startsWith('/') || /^https?:\/\//.test(path)) return path
    return IMG_BASE + path
}

function parseTitle(raw: string): TitlePart[] {
    const parts: TitlePart[] = []
    const re = /\[(img|anim):([^\]]+)\]/g
    let last = 0
    let m: RegExpExecArray | null
    while ((m = re.exec(raw)) !== null) {
        if (m.index > last) parts.push({ type: 'text', value: raw.slice(last, m.index) })
        parts.push({ type: m[1] as 'img' | 'anim', src: resolveImgSrc(m[2].trim()) })
        last = m.index + m[0].length
    }
    if (last < raw.length) parts.push({ type: 'text', value: raw.slice(last) })
    return parts
}

const titleParts = parseTitle(title)

const navRoutes = computed(() =>
    router.getRoutes().filter(r => r.meta?.version != null)
)

const seenVersions = computed(() => {
    const map = new Map<string, ReturnType<typeof useSetting<number>>>()
    for (const route of navRoutes.value) {
        const key = `page_version:${route.path}`
        map.set(route.path, useSetting<number>(key, 0))
    }
    return map
})

function isNew(path: string): boolean {
    const route = router.resolve(path)
    const currentVersion = (route.meta?.version as number | undefined) ?? 0
    const seen = seenVersions.value.get(path)
    return currentVersion > (seen?.value ?? 0)
}

router.afterEach((to) => {
    const version = to.meta?.version as number | undefined
    if (version == null) return
    const seen = seenVersions.value.get(to.path)
    if (seen && seen.value < version) {
        seen.value = version
    }
})

const group1Paths = [
    '/team-setup',
    '/my-kioku',
    '/heartphial',
    '/character-crys',
    '/portraits',
    '/kioku-grid',
].filter(Boolean)
const group2Paths = [
    '/profile',
    '/account-compare',
    '/sa-simulator-multiple',
    '/pve-simulator',
    '/pvp-simulator',
].filter(Boolean)
const group3Paths = [
    '/pvp-how-to',
    '/gacha-rate',
    '/link-raid',
    '/crys-reroll',
    '/tier-list-maker',
    '/about',
].filter(Boolean)

// The old single-hit model's pages (models/ScoreAttackTeam), kept next to each other on their own row.
const oldModelPaths = [
    '/sa-simulator-single',
    '/sa-simulator-multiple-old',
]

function routeForPath(path: string) {
    return router.getRoutes().find(r => r.path === path)
}
</script>

<template>
    <div id="app">
        <header>
            <CloudSyncWidget />
            <div class="title-row">
                <img :src="icon" alt="App Icon" class="app-icon" />
                <h1>
                    <template v-for="(part, i) in titleParts" :key="i">
                        <img v-if="part.type === 'img'" :src="part.src" alt="" class="title-img" />
                        <TitleSelfBuffAnim v-else-if="part.type === 'anim'" :src="part.src" />
                        <template v-else>{{ part.value }}</template>
                    </template>
                </h1>
            </div>
            <nav>
                <div v-for="paths in [group1Paths, group2Paths, group3Paths, oldModelPaths]">
                    <template v-for="path in paths" :key="path">
                        <router-link :to="path" :class="{ 'nav-new': isNew(path) }">
                            {{ routeForPath(path)?.name }}
                            <NewBadge v-if="isNew(path)" />
                        </router-link>
                    </template>
                </div>
                <div v-if="beta">
                    <router-link to="/beta">Beta Settings</router-link>
                    <router-link to="/analytics">Analytics</router-link>
                    <router-link to="/analytics-user">User Analytics</router-link>
                    <router-link to="/kanban">TO-DOs</router-link>
                </div>
            </nav>
        </header>

        <main>
            <router-view />
        </main>
    </div>
</template>


