<template>
    <div class="team-page">
        <h1 class="page-title">PvE Simulator</h1>

        <SavedTeamsPanel :saved="saved" />

        <section class="toolbar card share-card-actions">
            <div class="toolbar-left">
                <ImageActionsToolbar :target="() => shareCardRef!" filename="pve-simulator.png"
                    :export-options="exportOpts" :share-options="() => saved.shareOptions()"
                    :disabled="!teamKiokus.length" :share-handler="saved.generateShareUrl" share-label="Share team" />
            </div>
        </section>

        <!-- What the image export / share preview shows (hidden on the page). -->
        <div class="share-card-preview" ref="shareCardRef">
            <div class="share-header">
                <div class="share-stage">{{ stagePath(stageId) || 'No stage selected' }}</div>
                <div class="share-sub">{{ runSummary }}</div>
            </div>
            <div class="share-card-grid">
                <div v-for="(slot, index) in team.slots" :key="index" class="share-slot"
                    :class="{ 'share-slot-dealer': index === attackerIndex }">
                    <template v-if="slot.main">
                        <div v-if="index === attackerIndex" class="share-dealer-tag">Damage Dealer</div>
                        <div class="share-slot-top">
                            <div class="share-slot-kioku-image">
                                <img :src="kiokuImage(slot.main.id)" :alt="slot.main.name" />
                                <div class="share-overlay-badges">
                                    <span class="share-overlay-badge ascension">A{{ slot.main.ascension }}</span>
                                    <span class="share-overlay-badge heart">H{{ slot.main.heartphialLvl }}</span>
                                    <span class="share-overlay-badge magic">ML{{ slot.main.magicLvl }}</span>
                                    <span v-if="slot.main.rarity !== 3" class="share-overlay-badge special">SP{{
                                        slot.main.specialLvl
                                        }}</span>
                                </div>
                            </div>
                        </div>
                        <div class="share-slot-portrait-support">
                            <div v-if="slot.main.portrait" class="share-slot-portrait-block">
                                <img class="share-slot-portrait-icon" :src="portraitImage(slot.main.portrait)"
                                    :alt="slot.main.portrait" />
                                <div class="share-slot-label">{{ slot.main.portrait }}</div>
                            </div>
                            <div v-if="slot.support" class="share-slot-support-block">
                                <img class="share-slot-support-image" :src="kiokuImage(slot.support.id)"
                                    :alt="slot.support.name" />
                                <div class="share-slot-label">{{ slot.support.name }}</div>
                            </div>
                        </div>
                    </template>
                    <div v-else class="share-slot-empty">Empty</div>
                </div>
            </div>
            <div class="share-enemies-grid">
                <div v-for="(e, i) in enemyInfo" v-show="alive[i]" :key="e.id" class="share-enemy-slot">
                    <img class="share-enemy-img" :src="enemyImage(e.enemyMstId)" :alt="e.name" />
                    <div class="share-enemy-name">{{ e.name }}</div>
                    <div class="share-enemy-hp">HP {{ fmt(e.hp) }}<span v-if="e.gauges > 1"> ×{{ e.gauges }}</span>
                    </div>
                    <div class="share-enemy-toggles">
                        <span v-if="mainTargetIdx === i" class="share-chip">Target</span>
                        <span v-if="broken[i]" class="share-chip">Broken {{ breakRate[i] ?? e.maxRate }}%</span>
                    </div>
                </div>
            </div>
            <div class="share-results">
                <div v-if="dealer?.best" class="share-result">
                    <span class="share-result-label">Max damage · {{ dealer.name }} · {{ skillLabel(dealer.best)
                        }}</span>
                    <span class="share-result-value">{{ fmt(dealer.best.total.crit) }}</span>
                    <span class="share-result-sub">{{ fmt(dealer.best.total.avg) }} average</span>
                </div>
                <div v-if="battleResult || pending" class="share-result">
                    <span class="share-result-label">Battle simulator</span>
                    <span class="share-result-value" :class="pending ? 'waiting' : battleResult">{{ battleResultText
                        }}</span>
                    <span class="share-result-sub">after {{ actionCount }} action{{ actionCount === 1 ? '' : 's'
                        }}</span>
                </div>
            </div>
        </div>

        <!-- Stage -->
        <section class="card section-card">
            <h2 class="section-title">Stage</h2>
            <StagePicker v-model="stageId" />

            <StageWaveRows :s="stageView" :wiki-url="wikiUrl"
                wave-hint="Max Damage uses the enemies on the field when the selected wave starts; the battle simulator plays every wave. Untick Alive on an enemy to leave it out of Max Damage entirely."
                phase-hint="Max Damage uses the selected form, with the enemies on the field when it comes in." />
        </section>

        <!-- Enemies, in the same 5 columns as the team below -->
        <div v-if="enemyInfo.length" class="enemies-block">
            <h2 class="section-title page-section-title">Enemies <span class="title-sub">· wave {{ waveIdx + 1 }}<template v-if="phases.length"> · phase {{ phase }}</template></span>
            </h2>
            <EnemyCards :s="stageView" />

            <template v-for="row in extraEnemyRows" :key="row.title">
                <h3 class="enemy-row-title">{{ row.title }}</h3>
                <p class="enemy-row-hint">{{ row.hint }}</p>
                <div class="team-grid enemy-grid">
                    <div v-for="e in row.enemies" :key="e.id" class="enemy-card enemy-card-extra">
                        <div class="enemy-top">
                            <img class="enemy-img" :src="enemyImage(e.enemyMstId)" :alt="e.name" @error="hideImg" />
                            <div class="enemy-title">
                                <div class="enemy-name" :title="e.name">{{ e.name }}</div>
                                <div class="enemy-break">
                                    <template v-if="e.breakPoint > 0">Break {{ e.breakPoint }} · broken {{ e.initRate
                                        }}–{{ e.maxRate
                                        }}%</template>
                                    <template v-else>Can't be broken</template>
                                </div>
                            </div>
                        </div>
                        <div v-if="e.tag" class="enemy-tag">{{ e.tag }}</div>
                        <div class="enemy-stat-grid">
                            <div class="enemy-stat"><span class="enemy-stat-label">HP</span>
                                <span class="enemy-stat-value">{{ fmt(e.hp) }}<span v-if="e.gauges > 1" class="muted">
                                        ×{{ e.gauges
                                        }}</span></span>
                            </div>
                            <div class="enemy-stat"><span class="enemy-stat-label">ATK</span><span
                                    class="enemy-stat-value">{{
                                    fmt(e.atk) }}</span></div>
                            <div class="enemy-stat"><span class="enemy-stat-label">DEF</span><span
                                    class="enemy-stat-value">{{
                                    fmt(e.def) }}</span></div>
                            <div class="enemy-stat"><span class="enemy-stat-label">SPD</span><span
                                    class="enemy-stat-value">{{ e.spd
                                    }}</span></div>
                        </div>
                        <div v-if="e.weak.length" class="enemy-elements weak" title="Weak to">Weak
                            <img v-for="w in e.weak" :key="w" :src="`/exedra-dmg-calc/elements/${w}.png`" :alt="w"
                                :title="w" class="elem-icon" />
                        </div>
                        <!-- Every resisted element has the same rate, so one number covers them all. -->
                        <div v-if="e.resists.length" class="enemy-elements resist" title="Resists">Resist
                            <img v-for="r in e.resists" :key="r.el" :src="`/exedra-dmg-calc/elements/${r.el}.png`"
                                :alt="r.el" :title="r.el" class="elem-icon" />
                            −{{ e.resists[0].pct }}%
                        </div>
                    </div>
                </div>
            </template>
        </div>

        <!-- Team -->
        <h2 class="section-title page-section-title">Team</h2>
        <div class="team-grid">
            <div v-for="(slot, index) in team.slots" :key="index" class="team-slot"
                :class="{ dealer: attackerIndex === index, 'swap-source': swapSourceIndex === index }">
                <button type="button" class="dealer-slot-btn" :class="{ active: attackerIndex === index }"
                    :title="attackerIndex === index ? 'This member is the damage dealer' : 'Make this member the damage dealer'"
                    @click="attackerIndex = index">
                    <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">
                        <path d="M12 3l2.7 5.6 6.1.9-4.4 4.3 1 6.1L12 17l-5.4 2.9 1-6.1L3.2 9.5l6.1-.9z"
                            fill="currentColor" />
                    </svg>
                </button>
                <button type="button" class="swap-slot-btn" :class="{ active: swapSourceIndex === index }"
                    :title="swapSourceIndex === null ? 'Select this member to swap position' : swapSourceIndex === index ? 'Cancel swap' : 'Swap position with the selected member'"
                    @click="handleSwapClick(index)">
                    <svg viewBox="0 0 24 24" width="14" height="14" aria-hidden="true">
                        <path d="M6 3L2 7l4 4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
                            stroke-linejoin="round" />
                        <path d="M2 7h13" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
                            stroke-linejoin="round" />
                        <path d="M18 21l4-4-4-4" fill="none" stroke="currentColor" stroke-width="2"
                            stroke-linecap="round" stroke-linejoin="round" />
                        <path d="M22 17H9" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"
                            stroke-linejoin="round" />
                    </svg>
                </button>
                <h3 class="slot-title">
                    {{ index === attackerIndex ? 'Damage Dealer' : `Member ${index < attackerIndex ? index + 1 : index}`
                        }}
                    <AttackerOptimizer v-if="index === attackerIndex" :busy="loadoutBusy"
                        :disabled="!slot.main || !wave.length"
                        disabled-title="Pick a damage dealer and a stage first"
                        max-title="Find the best portrait, support & crystalis for the damage dealer (highest crit damage in Max Damage, on this wave)"
                        avg-title="Find the best portrait, support & crystalis for the damage dealer (highest average damage in Max Damage, on this wave)"
                        @optimize="optimizeAttackerLoadout" />
                </h3>
                <div v-if="index === attackerIndex && loadoutBusy" class="loadout-progress">
                    <span>Testing loadouts · {{ loadoutProgress.done }} / {{ loadoutProgress.total }}</span>
                    <button type="button" class="link-btn" @click="cancelLoadoutSearch">Cancel</button>
                </div>
                        <CharacterEditor :index="index" :slot="slot" :setMain="team.setMain"
                            :setSupport="team.setSupport" />
            </div>
        </div>

        <!-- Max damage -->
        <section class="card section-card">
            <h2 class="section-title">Max Damage <span v-if="maxDmgBusy" class="title-sub">· calculating…</span></h2>
            <p class="hint-text">The best case against wave {{ waveIdx + 1 }}<template v-if="phases.length">, phase {{ phase }}</template>: every buff and debuff listed under "Buffs
                &amp; Debuffs" below is active at the same time, at full stacks, with its conditions met. Effects that
                can't count together count once, whichever gives the most damage: tiers that exclude each other (like
                Light Chain Lv 1-5), and the same kind of buff from a skill
                and the switch skill replacing it, or from different follow-ups. Each skill is then launched in the
                game's battle code against this wave.</p>

            <p v-if="!teamKiokus.length" class="empty-hint">Add team members to calculate damage.</p>
            <template v-else-if="maxDmg">
                <!-- What was missing: the damage seen in game -> which buffs / debuffs taken away give it -->
                <div v-if="diagColumns.length" class="diag-block">
                    <div class="diag-head">
                        <span class="diag-title">Got less in game?</span>
                        <span class="diag-sub">Enter the damage you saw and find which buffs / debuffs were probably
                            missing.</span>
                    </div>
                    <div class="diag-fields">
                        <label class="field"><span class="field-label">In-game damage</span>
                            <input v-model.number="diagObserved" class="num diag-input" type="number" min="0" step="1"
                                placeholder="e.g. 1234567" @keydown.enter="runDiagnosis" /></label>
                        <div class="field"><span class="field-label">Skill</span>
                            <div class="diag-chips">
                                <button v-for="c in diagColumns" :key="c.id" type="button" class="chip"
                                    :class="{ active: diagColumnId === c.id }" @click="diagColumnId = c.id">{{ c.text }}</button>
                            </div>
                        </div>
                        <div class="field"><span class="field-label">Hit</span>
                            <SegmentedToggle v-model="diagHit" :options="DIAG_HIT_OPTIONS" />
                        </div>
                        <div v-if="maxDmg.enemies.length > 1" class="field"><span class="field-label">Damage on</span>
                            <div class="diag-chips">
                                <button type="button" class="chip" :class="{ active: diagEnemy === 'all' }"
                                    title="Summed over every enemy the skill hits" @click="diagEnemy = 'all'">All enemies</button>
                                <button v-for="(en, i) in maxDmg.enemies" :key="i" type="button" class="chip"
                                    :class="{ active: diagEnemy === i }" @click="diagEnemy = i">{{ i + 1 }}. {{ en.name }}</button>
                            </div>
                        </div>
                        <div class="diag-actions">
                            <button v-if="!diagBusy" type="button" class="btn btn-accent"
                                :disabled="!(diagObserved > 0) || maxDmgBusy" @click="runDiagnosis">Find what was missing</button>
                            <template v-else>
                                <span class="diag-progress">Testing · {{ diagProgress.done }} / {{ diagProgress.total }}</span>
                                <button type="button" class="link-btn" @click="cancelDiagnosis">Cancel</button>
                            </template>
                        </div>
                    </div>
                    <div v-if="diagResult" class="diag-results" :class="{ stale: diagStale }">
                        <p v-if="diagStale" class="diag-note diag-stale">These results are for the setup before your last
                            change. Click "Find what was missing" again to update them.</p>
                        <p v-if="diagResult.aboveMax" class="diag-note">{{ fmt(diagResult.observed) }} is more than this
                            page's Max Damage ({{ diagBaseText }}): nothing missing explains it. Check the levels, crystalis,
                            portraits and supports in the team, the stage and the wave, or whether it was a crit.</p>
                        <p v-else-if="diagResult.atMax" class="diag-note">{{ fmt(diagResult.observed) }} is this page's
                            Max Damage ({{ diagBaseText }}): nothing looks missing.</p>
                        <p v-else-if="!diagResult.rows.length" class="diag-note">No combination of up to 4 missing
                            buffs / debuffs gives {{ fmt(diagResult.observed) }} (Max Damage: {{ diagBaseText }}).</p>
                        <template v-else>
                            <p class="diag-note">Max Damage: {{ diagBaseText }}. Closest matches, best first (each
                                row run in the game's battle code with those effects taken away):</p>
                            <div v-for="(r, i) in diagRows" :key="i" class="diag-row"
                                :class="{ exact: Math.abs(r.diff) < 0.002 }">
                                <div class="diag-missing">
                                    <span v-for="(c, k) in r.missing" :key="c.id" class="diag-effect"
                                        :class="c.side === 'ally' ? 'diag-buff' : 'diag-debuff'"
                                        :title="r.alternatives[k].length ? 'Changes the damage exactly as much as: ' + r.alternatives[k].map(a => a.label).join(', ') : undefined">{{
                                            c.label }}<span v-if="r.alternatives[k].length" class="diag-alt"> or {{
                                            r.alternatives[k].map(a => a.label).join(' or ') }}</span></span>
                                </div>
                                <div class="diag-numbers">
                                    <span class="diag-dmg">{{ fmt(r.damage) }}</span>
                                    <span class="diag-hit">{{ r.hit === 'crit' ? 'crit' : 'no crit' }}</span>
                                    <span class="diag-diff" :title="'Compared with ' + fmt(diagResult.observed)">{{
                                        Math.abs(r.diff) < 0.002 ? 'match' : signedPct(r.diff * 100) }}</span>
                                    <button type="button" class="link-btn" title="Turn these off in Buffs & Debuffs below"
                                        @click="applyDiagnosis(r)">Apply</button>
                                </div>
                            </div>
                            <p class="diag-foot">Only buffs and debuffs Max Damage counts are tested (off, or at fewer
                                stacks). A close match is a likely answer, not a certain one: different effects can
                                add up to the same number.</p>
                        </template>
                    </div>
                </div>

                <div v-if="dealer?.best" class="result-block">
                    <div class="result-label">{{ dealer.name }} · {{ skillLabel(dealer.best) }}</div>
                    <div class="result-value">{{ fmt(dealer.best.total.crit) }} <span class="result-unit">if it
                            crits</span></div>
                    <div class="result-sub">{{ fmt(dealer.best.total.normal) }} without a crit · {{
                        fmt(dealer.best.total.avg) }}
                        on average at {{ dealer.best.critChance.toFixed(1) }}% crit rate</div>
                </div>

                <div class="sa-block">
                    <div class="sa-score-row" :title="saScoreTitle">
                        <span class="sa-score-label">Score Attack score (estimate)</span>
                        <span class="sa-score-value">{{ saScore }}</span>
                    </div>
                    <p v-if="!isScoreAttack" class="sa-hint">This stage is not a Score Attack stage; the score
                        uses {{ dealer?.name ?? 'the dealer' }}'s crit damage above with the numbers below.</p>
                    <div class="sa-fields">
                        <div v-if="saStageScore" class="field"
                            title="From the master data: the stage's fixed difficulty score, else the table value for its rank; the multiplier is the rank's difficulty coefficient">
                            <span class="field-label">Difficulty score ({{ saStageScore.isEx ? 'EX' : `rank ${saStageScore.difficulty}` }})</span>
                            <span>{{ saStageScore.difficultyScore.toLocaleString() }} · ×{{ saStageScore.coefficient.toFixed(2) }}</span></div>
                        <label v-else class="field"
                            title="To find: check the final score screen. This changes for each difficulty">
                            <span class="field-label">Difficulty score</span>
                            <input v-model.number="difficultyScore" type="number" /></label>
                        <label class="field"><span class="field-label">HP remaining (%)</span>
                            <input v-model.number="hpPercentTeam" type="number" step="1" min="0" max="100" /></label>
                        <label class="field"><span class="field-label">Turns</span>
                            <input v-model.number="saTurns" type="number" step="1" min="1" max="16" /></label>
                        <label class="field"
                            title="Damage per Max DMG point: (DMG shown under Max DMG) / (Max DMG points) on a result screen. Differs per Score Attack (e.g. 56, 140; Box Witch EX 9.5)">
                            <span class="field-label">Score multiplier</span>
                            <input v-model.number="scoreMultiplier" type="number" step="0.1" min="0" /></label>
                    </div>
                </div>

                <div class="table-wrap">
                    <table class="dmg-table">
                        <thead>
                            <tr>
                                <th>Member</th>
                                <th v-for="col in visibleDmgCols" :key="col.label" :title="col.title">{{ col.label }}
                                </th>
                            </tr>
                        </thead>
                        <tbody>
                            <tr v-for="m in maxDmg.members" :key="m.pos" :class="{ dealer: m.pos === dealerPos }">
                                <td>
                                    <div class="member-cell">
                                        <img v-if="memberId(m.pos)" class="member-thumb"
                                            :src="kiokuImage(memberId(m.pos)!)" :alt="m.name" />
                                        <span>{{ m.name }}</span>
                                        <span v-if="m.pos === dealerPos" class="dealer-badge">Dealer</span>
                                    </div>
                                </td>
                                <td v-for="col in visibleDmgCols" :key="col.label">
                                    <template v-if="col.get(m)">
                                        <div :title="perEnemyTitle(col.get(m)!)" class="dmg-crit">{{
                                            fmt(col.get(m)!.total.crit) }}</div>
                                        <div class="dmg-sub">{{ fmt(col.get(m)!.total.normal) }} · avg {{
                                            fmt(col.get(m)!.total.avg) }}</div>
                                        <div v-if="col.get(m)!.name || col.get(m)!.note" class="dmg-name">{{
                                            col.get(m)!.name }}<span v-if="col.get(m)!.note" class="dmg-note">{{
                                                col.get(m)!.name ? ' · ' : '' }}{{ col.get(m)!.note }}</span></div>
                                    </template>
                                    <span v-else class="muted">–</span>
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
                <p class="table-note">Big number: every hit crits. Below: no crits · average. Totals are summed over
                    every
                    enemy the skill hits; hover a value for the per-enemy split. Switch Skill and Follow-up show the
                    strongest one
                    the
                    member has.</p>
            </template>
        </section>

        <!-- Buffs & debuffs used by Max Damage, by where they come from -->
        <div v-if="maxDmg && maxDmg.effects.length" class="effects-block">
            <h2 class="section-title page-section-title">Buffs &amp; Debuffs</h2>
            <p class="hint-text">Every buff and debuff your team gives, grouped by what applies it. Max Damage counts
                the
                ones that are on: buffs on {{ dealerName }} (green) and debuffs on the enemies (red). Click one to turn
                it off
                or back on; lower its stacks to use fewer. Tiered effects and alternatives count one at a time (the one that gives the most damage):
                click another one to use it instead. A vortex always pops here, and a vortex user's vortex counts from one
                skill only: the Battle Skill's when they deal the damage, the Ultimate's otherwise (the other is off; click
                it to turn it on). On a wave with several enemies, the numbers on a vortex pick which enemies it is on; on a single-target buff, the portraits on a skill's top single-target buff pick which allies get all of that skill's single-target buffs (the dealer by default; another member's vortex / DoT damage uses its own buffs, and "while it has X" buffs follow X). A popped vortex or DoT deals its damage with its owner's own ATK and DMG buffs, so
                those count too ("Show support buffs" shows them in blue).</p>

            <div class="effects-summary">
                <span class="legend legend-buff">{{ effectCounts.buff }} buff{{ effectCounts.buff === 1 ? '' : 's' }} on
                    {{
                    dealerName }}</span>
                <span class="legend legend-debuff">{{ effectCounts.debuff }} debuff{{ effectCounts.debuff === 1 ? '' :
                    's' }}
                    on the enemies</span>
                <span v-if="effectCounts.off" class="legend legend-off">{{ effectCounts.off }} turned off</span>
                <button v-if="excluded.size || included.size || stacks.size || Object.keys(vortexEnemies).length || Object.keys(allyTargets).length" type="button" class="link-btn" @click="resetEffects">Reset
                    to the defaults</button>
                <span v-if="effectCounts.support && showSupportBuffs" class="legend legend-support">{{ effectCounts.support }}
                    support buff{{ effectCounts.support === 1 ? '' : 's' }}</span>
                <label v-if="effectCounts.support" class="chip" :class="{ active: showSupportBuffs }"
                    title="Self-only buffs of members whose vortex / DoT damage counts here: a vortex or popped DoT deals its damage with its owner's ATK and DMG buffs, so these are on the owner, not on the damage dealer. They count whether shown or not.">
                    <input type="checkbox" v-model="showSupportBuffs" /> Show support buffs
                </label>
                <label v-if="effectCounts.na" class="chip" :class="{ active: showUnreachable }"
                    title="Effects that only affect their own caster, or are limited to other elements/roles">
                    <input type="checkbox" v-model="showUnreachable" /> Show {{ effectCounts.na }} that can't reach {{
                    dealerName
                    }} or the enemies
                </label>
            </div>

            <div v-for="sec in effectSections" :key="sec.source" class="fx-section">
                <div class="fx-section-head">
                    <span class="fx-section-title">{{ sec.source }}</span>
                    <span class="fx-section-count">{{ sec.onCount }} of {{ sec.total }} on</span>
                    <button v-if="sec.total > 1" type="button" class="link-btn"
                        @click="setSectionOn(sec.toggleable, sec.onCount < sec.total)">{{ sec.onCount < sec.total
                            ? 'Turn all on' : 'Turn all off' }}</button>
                </div>
                <template v-for="row in sec.rows" :key="row.side">
                    <h4 class="fx-row-title" :class="row.side === 'ally' ? 'fx-row-buffs' : 'fx-row-debuffs'">{{
                        row.title }}</h4>
                    <!-- One cell per team slot, in the same columns as the team. -->
                    <div class="team-grid fx-grid">
                        <div v-for="(cell, slot) in row.cells" :key="slot" class="fx-cell">
                            <div v-if="cell.length" class="fx-cell-head">
                                <img v-if="team.slots[slot]?.main" class="fx-thumb"
                                    :src="kiokuImage(team.slots[slot].main!.id)" :alt="cell[0].casterName" />
                                <span class="fx-caster">{{ cell[0].casterName }}</span>
                            </div>
                            <div v-for="e in cell" :key="e.key" class="fx-card"
