import { useSavedTeams } from '../store/savedTeams'
import { PendingDecision, type RngDecision, type RngEvent, type RngMode } from '../models/BattleRng'
import { toast } from 'vue3-toastify'
import { TargetType, skillDetailId, type BattleSnapshot, type SkillDetail } from '../types/KiokuTypes'
import { stageWaves, summonTemplates, questStages, soloRaidInfo, isSoloRaidStage, multiRaidInfo } from '../models/PvE'
import { stageBattleType } from '../models/PvEBattle'
import passiveMstJson from '../assets/base_data/getPassiveSkillMstList.json'
import { getScoreAttackStage, scoreAttackStageScore, scoreAttackScoreParts, type ScoreAttackScoreInputs } from '../models/PvEScore'
import { isEffectValueType, type MaxDmgEffect, type MaxDmgResult, type MemberDamage, type SkillDamage } from '../models/MaxDamage'
import { buildSlotKioku, buildPvEExport, parsePvEExport, downloadText, exportToText, rekeyPicks, type PvEExport } from '../utils/pvpExport'
import { describePvESetup, sanitizePvESetup, stagePath, type PvESetup } from '../utils/pveSetup'
import { effectDescription, effectName, effectRestriction, effectValue } from '../utils/effectText'
import { passiveDetailsByMstId, portraits } from '../utils/helpers'
import { EngineBattle, type RaidCarry } from '../battle/EngineBattle'
import type { MaxDamageMessage, MaxDamageRequest } from '../workers/maxDamageWorker'
import { newMaxDamageWorker } from '../workers/newMaxDamageWorker'
import type { PvPKioku } from '../models/PvPKioku'
import AttackerOptimizer from '../components/AttackerOptimizer.vue'
import { useCharacterStore } from '../store/characterStore'
import { EngineLoadoutPool, findBestAttackerLoadoutEngine, loadoutSearch, mainWithLoadout, slotsWithLoadout, type AttackerLoadoutRow, type LoadoutMode } from '../models/EngineAttackerLoadout'
import type { LoadoutContext, VariantContext } from '../workers/maxDamageWorker'
import { diagnoseDamage, EngineVariantPool, mergeChanges, type DiagnosisCandidate, type DiagnosisResult, type DiagnosisRow, type HitKind } from '../models/EngineDamageDiagnosis'
import type { TeamSlot } from '../types/BestTeamTypes'
import type { MaxDmgOptions } from '../models/MaxDamage'
import type { HitTrace } from '../battle/EngineDamageTrace'
import { crystalises } from '../utils/helpers'
import { wikiBattleUrl } from '../utils/wikiBattlePage'
import { useStageEnemies, enemyView } from '../composables/useStageEnemies'
import StageWaveRows from '../components/StageWaveRows.vue'
import EnemyCards from '../components/EnemyCards.vue'

const team = useTeamStore()
const stageId = useSetting<number>('pveStageId', 982250)
const attackerIndex = useSetting('pveAttackerIndex', 2)

// Swap two members' positions (main + support). The damage dealer star follows its kioku.
const swapSourceIndex = ref<number | null>(null)
const swapSlots = (a: number, b: number) => {
    const { main: aMain, support: aSupport } = team.slots[a]
    const { main: bMain, support: bSupport } = team.slots[b]
    team.setMain(a, bMain)
    team.setSupport(a, bSupport)
    team.setMain(b, aMain)
    team.setSupport(b, aSupport)
    if (attackerIndex.value === a) attackerIndex.value = b
    else if (attackerIndex.value === b) attackerIndex.value = a
}
const handleSwapClick = (index: number) => {
    if (swapSourceIndex.value === null) swapSourceIndex.value = index
    else if (swapSourceIndex.value === index) swapSourceIndex.value = null
    else {
        swapSlots(swapSourceIndex.value, index)
        swapSourceIndex.value = null
    }
}
const scoreMultiplier = useSetting('scoreMultiplier', 35)
const saTurns = useSetting('turns', 3)
const hpPercentTeam = useSetting('hp_percentage_team', 20)
const difficultyScore = useSetting('difficulty_score', 6_000_000)
const simTurns = useSetting('pveSimTurns', 40)

const fmt = (n: number) => Math.round(n).toLocaleString()
const hideImg = (ev: Event) => { (ev.target as HTMLImageElement).style.visibility = 'hidden' }
const kiokuImage = (id: number) => `/exedra-dmg-calc/kioku_images/${id}_thumbnail.png`
const enemyImage = (enemyMstId: number) => `/exedra-dmg-calc/enemy/${enemyMstId}_thumbnail.png`
const portraitImage = (portrait: string) => portraits[portrait] ? `/exedra-dmg-calc/portrait_images/${portraits[portrait].resourceName}_thumbnail.png` : ''

// ---- stage / enemies ----
// Shared with the Highest Dmg Calc (composables/useStageEnemies, StageWaveRows, EnemyCards): wave, boss phase (Crisis
// "phase 1/2/3": Max Damage uses one form), adds summoned mid-fight (on the field), and per enemy alive / target / broken / rate.
const waveIdx = ref(0)
const phase = ref(1)
const se = useStageEnemies(stageId, waveIdx, phase)
const stageView = reactive(se)
const { waves, waveMeta, phases, wave, aliveWave, aliveInfo, alive, mainTargetIdx, broken, breakRate, enemyInfo, formLabel } = se
const wikiUrl = computed(() => stageId.value ? wikiBattleUrl(stageId.value) : undefined)
const currentPhase = () => se.phasePos.value
// Endless waves list more than 5 enemies: only 5 can be on the field, the rest come in as those are defeated.
// Summons are defined for the whole stage (identical templates shown once).
const extraEnemyRows = computed(() => {
    const backups = (waveMeta.value?.appearances ?? []).slice(wave.value.length).map(a => enemyView(a))
    const seen = new Set<string>()
    const summons = [...(stageId.value ? summonTemplates(stageId.value).values() : [])].map(a => enemyView(a)).filter(e => {
        const key = `${e.enemyMstId}:${e.hp}:${e.atk}:${e.def}:${e.spd}`
        return !seen.has(key) && !!seen.add(key)
    })
    const forms = (waveMeta.value?.modeChanges ?? []).filter(m => m.step !== currentPhase()).map(m => enemyView(m.appearance, formLabel(m)))
    return [
        { title: 'Other forms', enemies: forms, hint: 'The boss above changes form when its HP drops to each threshold, keeping its position. Pick a phase above to use another form in Max Damage.' },
        { title: 'Backups', enemies: backups, hint: 'Only 5 enemies can be on the field at once. These wait in the back and come in as the ones on the field are defeated. Not part of Max Damage.' },
        { title: 'Summons', enemies: summons, hint: 'Enemies that can be summoned during the battle. Not part of Max Damage, except the adds on the field above and the ones a boss form brings in when its phase starts (shown above when that phase is selected).' },
    ].filter(r => r.enemies.length)
})

// ---- team ----
// Members in slot order; an empty slot is skipped (quests can be played with fewer than 5).
const filledSlots = computed(() => team.slots.map((s, i) => [s, i] as const).filter(([s]) => !!s.main))
const teamKiokus = computed<PvPKioku[]>(() => {
    try {
        return filledSlots.value.map(([s]) => markRaw(buildSlotKioku(s)))
    } catch (e) {
        console.warn('Could not build team', e)
        return []
    }
})
const dealerPos = computed(() => Math.max(0, filledSlots.value.findIndex(([, i]) => i === attackerIndex.value)))
const memberId = (pos: number) => filledSlots.value[pos]?.[0].main?.id

// ---- max damage ----
const excluded = reactive(new Set<string>())
// Effects that are off by default (MaxDmgEffect.defaultOff: a vortex user's other vortex) and were turned on.
const included = reactive(new Set<string>())
const stacks = reactive(new Map<string, number>())
// A vortex put on chosen enemies (effect key -> page enemy indexes, [] = off): replaces its default and on/off.
const vortexEnemies = reactive<Record<string, number[]>>({})
// A single-target ally buff (range 1) given to chosen allies (effect key -> team positions, [] = off) instead of the
// dealer only: another member's vortex / DoT damage uses that member's own buffs.
const allyTargets = reactive<Record<string, number[]>>({})
const isOffByDefault = (k: string) => !!maxDmg.value?.effects.find(x => x.key === k)?.defaultOff
// A rung of a tier ladder (MaxDmgEffect.tier, one rung counts at a time; the engine uses the rung that gives the most
// damage): clicking the rung in use turns the whole ladder off; clicking any other rung uses that one only.
const toggleEffect = (k: string) => {
    const e = maxDmg.value?.effects.find(x => x.key === k)
    // a vortex on chosen enemies: off everywhere, or (when off) on every enemy
    if (vortexEnemies[k]) {
        vortexEnemies[k] = vortexEnemies[k].length ? [] : (maxDmg.value?.enemies ?? []).map((_, i) => i)
        return
    }
    // single-target ally buffs given to chosen allies: the top card (the group's anchor) turns the whole skill off, or
    // (when off) back on the dealer; the others turn off / on one by one
    const g = e?.allyGroup
    if (g && allyTargets[g] && !excluded.has(k)) {
        if (k === g) allyTargets[g] = allyTargets[g].length ? [] : [dealerPos.value]
        else excluded.add(k)
        return
    }
    if (e?.tier) {
        const inUse = !excluded.has(k) && !e.tierUsed && !!e.reach
        if (inUse) e.tier.keys.forEach(key => excluded.add(key))
        else e.tier.keys.forEach(key => { if (key !== k) excluded.add(key); else excluded.delete(key) })
        return
    }
    if (isOffByDefault(k)) {
        excluded.delete(k)
        if (included.has(k)) included.delete(k); else included.add(k)
        return
    }
    if (excluded.has(k)) excluded.delete(k); else excluded.add(k)
}
const setStacks = (k: string, v: number, max: number) => {
    const n = Math.max(0, Math.min(max, Number.isFinite(v) ? v : max))
    if (n === max) stacks.delete(k); else stacks.set(k, n)
}
const resetEffects = () => {
    excluded.clear(); included.clear(); stacks.clear()
    for (const k of Object.keys(vortexEnemies)) delete vortexEnemies[k]
    for (const k of Object.keys(allyTargets)) delete allyTargets[k]
}
// One ally chip on the top single-target buff card of a skill: gives that skill's single-target buffs to that ally
// too, or takes them away.
function toggleAllyTarget(e: EffectView, i: number) {
    const on = new Set(e.status === 'off' ? [] : e.onAllies)
    if (on.has(i)) on.delete(i); else on.add(i)
    allyTargets[e.key] = [...on].sort((a, b) => a - b)
}
// One enemy chip of a vortex card: puts the vortex on that enemy or takes it off (starting from where it is now).
function toggleVortexEnemy(e: EffectView, i: number) {
    const on = new Set(e.onEnemies)
    if (on.has(i)) on.delete(i); else on.add(i)
    vortexEnemies[e.key] = [...on].sort((a, b) => a - b)
}

// Computed in a worker (workers/maxDamageWorker.ts: battle/EngineMaxDamage, the game's own battle code); the last
// result stays on screen while a new one is computed (`maxDmgBusy`).
const maxDmg = shallowRef<MaxDmgResult | undefined>()
const maxDmgBusy = ref(false)
let maxDmgWorker: Worker | undefined
let maxDmgReq = 0
// Solo Raid party buff (the battle's and Max Damage's)
const partyBuffId = useSetting<number>('pveRaidPartyBuff', 0)
// The page's Max Damage inputs (also the attacker loadout search's, so it scores what the panel shows).
function maxDmgOpts(): MaxDmgOptions {
    return {
        battleType: stageBattleType(stageId.value),
        excluded: new Set(excluded), included: new Set(included), stacks: new Map(stacks),
        vortexEnemies: JSON.parse(JSON.stringify(vortexEnemies)),
        allyTargets: JSON.parse(JSON.stringify(allyTargets)),
        ...se.maxDmgEnemyOpts(),
        partyBuffId: isSoloRaidStage(stageId.value) ? partyBuffId.value || undefined : undefined,
    }
}
const currentWaveIdx = () => se.wavePos.value
function requestMaxDamage() {
    if (!teamKiokus.value.length || !aliveWave.value.length) { maxDmg.value = undefined; maxDmgBusy.value = false; return }
    try {
        if (!maxDmgWorker) {
            maxDmgWorker = newMaxDamageWorker()
            maxDmgWorker.onmessage = (e: MessageEvent<MaxDamageMessage>) => {
                if (e.data.id !== maxDmgReq) return
                maxDmgBusy.value = false
                if (e.data.error) { console.warn('Max damage failed', e.data.error); maxDmg.value = undefined; return }
                maxDmg.value = markRaw(e.data.result!)
            }
            maxDmgWorker.onerror = (e) => { console.warn('Max damage worker failed', e.message); maxDmgBusy.value = false }
        }
        maxDmgBusy.value = true
        maxDmgWorker.postMessage({
            id: ++maxDmgReq,
            slots: JSON.parse(JSON.stringify(filledSlots.value.map(([s]) => s))),
            stageId: stageId.value, waveIdx: currentWaveIdx(), phase: currentPhase(),
            wave: JSON.parse(JSON.stringify(aliveWave.value)), dealerPos: dealerPos.value,
            opts: { ...maxDmgOpts(), trace: statsForNerds.value },
        } satisfies MaxDamageRequest)
    } catch (e) {
        console.warn('Max damage failed', e)
        maxDmgBusy.value = false
    }
}
// "Stats for nerds" (collapsed by default): the engine's damage steps for the dealer's best skill, recorded only while open
const statsForNerds = useSetting('pveStatsForNerds', false)
// a vortex's chosen enemies are indexes of the enemies alive: they start over when one dies / comes back
watch(alive, (a, old) => { if (old && a.length === old.length && a.some((x, i) => x !== old[i])) for (const k of Object.keys(vortexEnemies)) delete vortexEnemies[k] })
watch([teamKiokus, aliveWave, dealerPos, () => [...excluded], () => [...included], () => JSON.stringify(vortexEnemies), () => JSON.stringify(allyTargets), () => [...stacks], broken, breakRate, mainTargetIdx, partyBuffId], requestMaxDamage, { deep: true, immediate: true })
watch(statsForNerds, open => { if (open && !maxDmg.value?.trace) requestMaxDamage() })
onBeforeUnmount(() => { maxDmgWorker?.terminate(); loadoutPool?.close() })
const dealer = computed(() => maxDmg.value?.members[dealerPos.value])
const dealerName = computed(() => dealer.value?.name ?? 'the damage dealer')
const skillOf = (m: MemberDamage, t: TargetType) => m.skills.find(s => s.type === t)
// Switch skill: the strongest skill a SWITCH_SKILL state swaps in (e.g. Falsified Phenomena's battle skill while her
// field is up). Follow-up: the strongest AdditionalSkill / Ether Blow the kit can trigger, on top of an action.
const dmgCols: { label: string, title?: string, get: (m: MemberDamage) => SkillDamage | undefined }[] = [
    { label: 'Ultimate', get: m => skillOf(m, TargetType.specialId) },
    { label: 'Battle Skill', get: m => skillOf(m, TargetType.skillId) },
    { label: 'Basic Attack', get: m => skillOf(m, TargetType.attackId) },
    { label: 'Switch Skill', title: 'A skill that replaces one of the above while its condition holds (e.g. while a field is up). Strongest one if there are several.', get: m => m.switchSkill },
    { label: 'Follow-up', title: 'Damage of one follow-up / Ether Blow, dealt on top of an action. Strongest one if there are several.', get: m => m.followUp },
]
// Hide a column when no team member has anything in it (e.g. no Switch Skills or Follow-ups in the team)
const visibleDmgCols = computed(() => dmgCols.filter(col => maxDmg.value?.members.some(m => col.get(m))))
const skillLabel = (s: SkillDamage) => s.name ? `${s.label} (${s.name})` : s.label
const perEnemyTitle = (s: SkillDamage) => s.perEnemy.map((x, i) => x.crit ? `${aliveInfo.value[i]?.name}: ${fmt(x.crit)} crit / ${fmt(x.normal)} / avg ${fmt(x.avg)}` : '').filter(Boolean).join('\n')

// ---- find best attacker loadout (models/EngineAttackerLoadout): portrait, support and crystalis of the damage dealer
// that give the highest Max Damage above (crit total, or average total), with everything else as on the page
const characterStore = useCharacterStore()
const loadoutBusy = ref(false)
const loadoutProgress = reactive({ done: 0, total: 0 })
let loadoutPool: EngineLoadoutPool | null = null
let loadoutCancelled = false
const cancelLoadoutSearch = () => { loadoutCancelled = true; loadoutPool?.close() }
const plain = <T,>(x: T): T => JSON.parse(JSON.stringify(x))
const loadoutText = (r: AttackerLoadoutRow) => [r.portrait, r.support?.name ?? 'no support',
    r.crysIds.map(id => crystalises[id]?.name ?? id).join(', ')].filter(Boolean).join(' · ')

async function optimizeAttackerLoadout(mode: LoadoutMode) {
    const slot = team.slots[attackerIndex.value]
    if (loadoutBusy.value || !slot?.main || !aliveWave.value.length) return
    const pos = dealerPos.value
    const slots = plain(filledSlots.value.map(([s]) => s)) as TeamSlot[]
    // what the panel shows now (the search fills empty sub crystalis with the defaults, so its start can differ)
    const d = maxDmg.value?.members[pos]
    const cols = d ? [...d.skills, ...(d.switchSkill ? [d.switchSkill] : [])] : []
    const nowValue = cols.length ? Math.max(...cols.map(c => mode === 'avg' ? c.total.avg : c.total.crit)) : undefined
    let search: ReturnType<typeof loadoutSearch>
    try {
        search = loadoutSearch(plain(slot.main), slot.support ? plain(slot.support) : undefined,
            slots.map(s => s.main!.name), plain(characterStore.characters.filter(c => c.enabled)), mode,
            { portrait: !!slot.portraitLocked, support: !!slot.supportLocked })
    } catch (e) {
        toast.error(String((e as Error)?.message ?? e), { position: toast.POSITION.TOP_RIGHT, icon: false })
        return
    }
    const context: LoadoutContext = { stageId: stageId.value, waveIdx: currentWaveIdx(), phase: currentPhase(), wave: plain(aliveWave.value), dealerPos: pos, opts: maxDmgOpts() }
    const pool = loadoutPool = new EngineLoadoutPool(context, undefined, err => console.warn('Loadout score failed', err))
    loadoutBusy.value = true
    loadoutCancelled = false
    loadoutProgress.done = 0
    loadoutProgress.total = 0
    try {
        const { rows } = await findBestAttackerLoadoutEngine(search, mode, l => pool.score(slotsWithLoadout(slots, pos, l)),
            (done, total) => { loadoutProgress.done = done; loadoutProgress.total = total }, () => loadoutCancelled)
        if (loadoutCancelled) return
        const best = rows[0]
        if (!best) {
            toast.error("Couldn't score any loadout for this damage dealer", { position: toast.POSITION.TOP_RIGHT, icon: false })
            return
        }
        // the team may have changed while searching: only apply to the same dealer
        const now = team.slots[attackerIndex.value]
        if (now?.main?.name !== slot.main.name) return
        const what = mode === 'avg' ? 'average' : 'crit'
        if (nowValue !== undefined && best.value <= nowValue) {
            toast.info(`The current loadout is already the best one found (${fmt(nowValue)} ${what} damage, ${rows.length} loadouts tested)`, { position: toast.POSITION.TOP_RIGHT, icon: false })
            return
        }
        const updated = mainWithLoadout(now.main, best)
        now.main.portrait = updated.portrait
        for (const [id, o] of Object.entries(updated.crysOptions)) {
            const cur = now.main.crysOptions[Number(id)]
            if (cur) { cur.useIndex = o.useIndex; cur.subCrys = o.subCrys }
            else now.main.crysOptions[Number(id)] = o
        }
        const supportChar = best.support && characterStore.characters.find(c => c.name === best.support!.name)
        if (supportChar) team.setSupport(attackerIndex.value, supportChar)
        toast.success(`${loadoutText(best)}: ${fmt(best.value)} ${what} damage${nowValue !== undefined ? ` (was ${fmt(nowValue)})` : ''}`, { position: toast.POSITION.TOP_RIGHT, icon: false })
    } finally {
        pool.close()
        if (loadoutPool === pool) loadoutPool = null
        loadoutBusy.value = false
    }
}

// ---- what was missing (models/EngineDamageDiagnosis): the damage seen in game for one of the dealer's skills -> which
// of the effects Max Damage counts (cards 'used' / 'partial' below) taken away give it, on the page's other choices
type DiagCandidate = DiagnosisCandidate & { side: 'ally' | 'enemy' }
const DIAG_HIT_OPTIONS = [
    { value: 'crit', label: 'Crit' }, { value: 'normal', label: 'No crit' },
    { value: 'either', label: 'Not sure', title: 'Try both: crit and no crit' },
] as const
const diagObserved = ref<number>(NaN)
const diagHit = ref<HitKind | 'either'>('crit')
const diagEnemy = ref<number | 'all'>('all')
const diagColumnId = ref('')
const diagBusy = ref(false)
const diagProgress = reactive({ done: 0, total: 0 })
const diagResult = shallowRef<(DiagnosisResult<DiagCandidate> & { observed: number, hit: HitKind | 'either' }) | undefined>()
let diagPool: EngineVariantPool | null = null
let diagCancelled = false
// The dealer's columns that can be checked (skills + switch skill; a follow-up comes on top of an action)
const diagColumns = computed(() => {
    const d = dealer.value
    if (!d) return []
    return [...d.skills, ...(d.switchSkill ? [d.switchSkill] : [])].filter(s => s.total.crit > 0)
        .map(s => ({ id: `${s.label}|${s.name ?? ''}`, text: skillLabel(s), label: s.label, name: s.name }))
})
watch(diagColumns, cols => {
    if (!cols.some(c => c.id === diagColumnId.value)) {
        const best = dealer.value?.best
        diagColumnId.value = cols.find(c => best && c.id === `${best.label}|${best.name ?? ''}`)?.id ?? cols[0]?.id ?? ''
    }
}, { immediate: true })
watch(() => maxDmg.value?.enemies.length ?? 0, n => { if (diagEnemy.value !== 'all' && diagEnemy.value >= n) diagEnemy.value = 'all' })
// Results are for the setup they were run on: a new Max Damage (team, wave, toggles, "Apply") marks them as older
const diagStale = ref(false)
watch(maxDmg, () => { if (!diagBusy.value && diagResult.value) diagStale.value = true })
// The closest rows only: within 1% of the in-game number, or twice as far off as the best row (at most 6)
const diagRows = computed(() => {
    const rows = diagResult.value?.rows ?? []
    const limit = Math.max(0.01, 2 * Math.abs(rows[0]?.diff ?? 0))
    return rows.filter(r => Math.abs(r.diff) <= limit).slice(0, 6)
})
const diagBaseText = computed(() => {
    const b = diagResult.value?.base
    if (!b) return ''
    return [b.crit !== undefined ? `${fmt(b.crit)} crit` : '', b.normal !== undefined ? `${fmt(b.normal)} no crit` : ''].filter(Boolean).join(' / ')
})

// Taking a card away: every effect of it off (a vortex on chosen enemies: off on all of them); a stackable one also at
// fewer stacks (1, and half).
function diagCandidates(): DiagCandidate[] {
    const out: DiagCandidate[] = []
    for (const e of effectViews.value) {
        if (e.status !== 'used' && e.status !== 'partial') continue
        const who = `${e.casterName} ${e.source}`
        const what = `${e.name}${e.value ? ' ' + e.value : ''}`
        const vortexOff: Record<string, number[]> = {}
        const off: string[] = []
        for (const k of e.keys) { if (vortexEnemies[k]) vortexOff[k] = []; else off.push(k) }
        const bucket = `${e.type}|${e.side}`
        out.push({ id: `${e.key}:off`, group: e.key, side: e.side, bucket, label: `${what} (${who})${e.tierGroup ? ', lower tier' : ''}`, change: { excluded: off, vortexEnemies: vortexOff } })
        if (e.maxStacks > 1 && e.stacks > 1) {
            for (const n of [...new Set([1, Math.floor(e.stacks / 2)])].filter(n => n >= 1 && n < e.stacks)) {
                out.push({
                    id: `${e.key}:${n}`, group: e.key, side: e.side, bucket, label: `${e.name} at ${n}/${e.maxStacks} stacks (${who})`,
                    change: { stacks: e.keys.map((k, i) => [k, i ? 0 : n] as [string, number]) },
                })
            }
        }
    }
    return out
}

const cancelDiagnosis = () => { diagCancelled = true; diagPool?.close() }
async function runDiagnosis() {
    const col = diagColumns.value.find(c => c.id === diagColumnId.value)
    const observed = diagObserved.value
    if (diagBusy.value || !col || !(observed > 0) || !aliveWave.value.length) return
    const hit = diagHit.value
    const context: VariantContext = {
        slots: plain(filledSlots.value.map(([s]) => s)) as TeamSlot[], stageId: stageId.value, waveIdx: currentWaveIdx(), phase: currentPhase(),
        wave: plain(aliveWave.value), dealerPos: dealerPos.value, opts: { ...maxDmgOpts(), onlyColumn: col.label },
    }
    const pool = diagPool = new EngineVariantPool(context, undefined, err => console.warn('Damage check failed', err))
    diagBusy.value = true
    diagCancelled = false
    diagProgress.done = 0
    diagProgress.total = 0
    diagResult.value = undefined
    try {
        const r = await diagnoseDamage(diagCandidates(), { column: { label: col.label, name: col.name }, enemy: diagEnemy.value, hit, observed },
            c => pool.score(c), (done, total) => { diagProgress.done = done; diagProgress.total = total }, () => diagCancelled)
        if (diagCancelled) return
        if (!r) { toast.error("Couldn't evaluate this skill", { position: toast.POSITION.TOP_RIGHT, icon: false }); return }
        diagResult.value = { ...r, observed, hit }
        diagStale.value = false
    } finally {
        pool.close()
        if (diagPool === pool) diagPool = null
        diagBusy.value = false
    }
}
onBeforeUnmount(() => diagPool?.close())

// "Apply": the row's effects off (or at its stacks) in Buffs & Debuffs, so Max Damage shows that case
function applyDiagnosis(r: DiagnosisRow<DiagCandidate>) {
    const c = mergeChanges(r.missing.map(m => m.change))
    for (const k of c.excluded ?? []) { excluded.add(k); included.delete(k) }
    for (const [k, v] of Object.entries(c.vortexEnemies ?? {})) vortexEnemies[k] = v
    for (const [k, n] of c.stacks ?? []) stacks.set(k, n)
    toast.info(`Turned off: ${r.missing.map(m => m.label).join(', ')}`, { position: toast.POSITION.TOP_RIGHT, icon: false })
}

// ---- stats for nerds: what the engine computed for the dealer's best skill (MaxDmgResult.trace)
const nerdTrace = computed(() => statsForNerds.value ? maxDmg.value?.trace : undefined)
const ELEMENT_NAMES: Record<number, string> = { 1: 'Flame', 2: 'Aqua', 3: 'Forest', 4: 'Light', 5: 'Dark', 6: 'Void' }
const elName = (e: number) => ELEMENT_NAMES[e] ?? (e ? `Element ${e}` : 'None')
const pct = (f: number) => `${+(f * 100).toFixed(1)}%`
const signedPct = (v: number) => `${v > 0 ? '+' : ''}${+v.toFixed(1)}%`
const line = (label: string, value: string | number) => `${label.padEnd(16)}- ${typeof value === 'number' ? fmt(value) : value}`
// Factors that apply per hit; a group shows "(varies)" when its hits differ.
const FACTORS: [string, (h: HitTrace) => number][] = [
    ['Break factor', h => h.breakFactor], ['DEF factor', h => h.defFactor], ['DMG dealt fact', h => h.giveFactor],
    ['DMG taken fact', h => h.receiveFactor], ['Elem res fact', h => h.resistFactor], ['Weak elem fact', h => h.weakFactor],
    ['Crit factor', h => h.critFactor], ['Difficulty fact', h => h.difficultyFactor], ['Final give fact', h => h.finalGiveFactor],
    ['Shield factor', h => h.shieldFactor],
]
const nerdCalc = computed(() => {
    const t = nerdTrace.value
    if (!t) return []
    return t.enemies.map((en, i) => {
        const hits = t.hits.filter(h => h.enemyIdx === i)
        const out: string[] = [line('Skill', t.skill)]
        // one block per attacker + kind of hit (a vortex / DoT goes through its owner's pipeline)
        const groups = new Map<string, HitTrace[]>()
        for (const h of hits) { const k = `${h.category} · ${h.attacker}`; groups.set(k, [...(groups.get(k) ?? []), h]) }
        for (const [k, g] of groups) {
            const h = g[0]
            const varies = (f: (x: HitTrace) => number) => g.some(x => Math.abs(f(x) - f(h)) > 1e-9) ? ' (varies)' : ''
            out.push('', `[${k}] ×${g.length}`)
            if (h.statType) out.push(line(`${h.statType} (buffed)`, h.atk ?? h.stat ?? 0))
            if (h.stat !== undefined && h.atk !== undefined && Math.round(h.stat) !== Math.round(h.atk)) out.push(line(`Base from ${h.statType}`, h.stat))
            if (h.def !== undefined) out.push(line('Enemy DEF', h.def))
            if (h.resist !== undefined) out.push(line('Elem resist', `${signedPct(h.resist)} (${elName(h.element)})`))
            for (const [label, f] of FACTORS) out.push(line(label, pct(f(h)) + varies(f)))
            g.forEach((x, n) => out.push(`  ${String(n + 1).padStart(2)}. ${x.power !== undefined ? `${pct(x.power).padStart(7)} ` : ''}base ${fmt(x.base)} → ${fmt(x.preCrit)}${x.crit ? ' → crit' : ''} = ${fmt(x.result)}`))
            out.push(line('Subtotal', g.reduce((s, x) => s + x.result, 0)))
        }
        const traced = hits.reduce((s, x) => s + x.result, 0)
        const dealt = t.dealt[i] ?? 0
        out.push('')
        if (dealt !== traced) out.push(line('Other (final..)', dealt - traced))
        out.push(line('Result', dealt))
        return { title: en?.name ?? aliveInfo.value[i]?.name ?? `Enemy ${i + 1}`, text: hits.length || dealt ? out.join('\n') : `${line('Skill', t.skill)}\n\nNot hit.` }
    })
})
const nerdEnemies = computed(() => {
    const t = nerdTrace.value
    if (!t) return []
    return t.enemies.map((en, i) => {
        if (!en) return { title: aliveInfo.value[i]?.name ?? `Enemy ${i + 1}`, text: '(not on the field)' }
        const brk = !en.canBreak ? "can't break" : en.broken ? `broken, ${en.breakRate}% DMG (max ${en.maxBreakRate}%)` : 'not broken'
        return {
            title: en.name, text: [
                line('Enemies alive', t.enemies.filter(Boolean).length),
                line('HP', en.hp),
                line('Base DEF', en.defBase),
                line('DEF (debuffed)', en.def),
                line('DEF change', en.defBase ? signedPct((en.def / en.defBase - 1) * 100) : '–'),
                line('Break', brk),
                line('Weak to', en.weakElements.length ? en.weakElements.map(elName).join(', ') : 'nothing'),
                line(`Res vs ${elName(t.dealer.element)}`, signedPct(en.resist)),
                line('Crit rate taken', signedPct(en.rcvCtr)),
                line('Crit DMG taken', signedPct(en.rcvCtd)),
                line('States on it', en.states),
            ].join('\n'),
        }
    })
})
const nerdKioku = computed(() => {
    const t = nerdTrace.value
    if (!t) return []
    return t.allies.map((u, pos) => {
        const k = teamKiokus.value[pos] as any
        const slot = filledSlots.value[pos]?.[0]
        const m = slot?.main
        const lines: string[] = []
        if (k && m) {
            const asc = k.ascension ?? 0
            lines.push(
                line('Kioku Lvl', k.kiokuLvl), line('Ascension', asc), line('Magic Lvl', k.magicLvl), line('Heartphial Lvl', k.heartphialLvl),
                line('Ult / Skill Lvl', `${k.specialLvl} / ${k.skillLvl}`), line('Ability / Basic', `${k.abilityLvl} / ${k.attackLvl}`),
                line('Portrait', m.portrait || 'none'),
                line('Support', slot?.support ? `${slot.support.name} (Lv ${k.support?.supportLvl ?? '?'})` : 'none'),
                line('Crystalis', ((k.inputCrysIDs ?? []) as number[]).map(id => crystalises[id]?.name ?? id).join(', ') || 'none'),
                '',
                line('Kioku ATK', Math.floor(k.kiokuAtk ?? 0)),
                line('Ascension ATK', Math.floor((k.kiokuAtk ?? 0) * 0.02 * asc)),
                line('Portrait ATK', k.portrait?.stats?.[5]?.atk ?? 0),
                line('Support ATK', Math.floor((k.support?.getBaseAtk?.() ?? 0) * 0.16)),
                line('Magic ATK', k.magicAtk ?? 0), line('Heartphial ATK', k.heartAtk ?? 0),
                line('Base ATK (app)', k.getBaseAtk?.() ?? 0),
                '',
            )
        }
        lines.push(
            line('Base ATK (eng.)', u.atkBase), line('ATK (buffed)', u.atk),
            line('Base DEF', u.defBase), line('DEF (buffed)', u.def),
            line('Max HP', u.hp),
            line('Base SPD', u.spdBase), line('SPD (buffed)', +u.spd.toFixed(2)),
            line('Crit rate', `${+u.ctrBase.toFixed(1)}% → ${+u.ctr.toFixed(1)}%`),
            line('Crit DMG', `${+u.ctdBase.toFixed(1)}% → ${+u.ctd.toFixed(1)}%`),
            line('Element', elName(u.element)),
            line('States on it', u.states),
        )
        return { title: `${u.name}${pos === dealerPos.value ? ' (dealer)' : ''}`, text: lines.join('\n') }
    })
})

// ---- buffs & debuffs: where each effect comes from and whether it counts ----
// 'alt': a rung of a tier ladder left out because another rung of it is used (MaxDmgEffect.tierUsed).
type EffectStatus = 'used' | 'partial' | 'alt' | 'off' | 'na'
const STATUS_ORDER: Record<EffectStatus, number> = { used: 0, partial: 1, alt: 2, off: 3, na: 4 }
// Sections, in this order: active skills first, then the kit's passives and what's equipped.
const SOURCE_ORDER = ['Battle Skill', 'Ultimate', 'Basic Attack', 'Switch Skill', 'Follow-up', 'Ability', 'Ascension', 'Crystalis', 'Portrait', 'Support', 'Passive', 'Stage']
const showUnreachable = useSetting('pveShowUnreachableEffects', false)
// Buffs on a vortex / DoT owner who isn't the dealer (MaxDmgEffect.forOwner): hidden unless asked for, still counted.
const showSupportBuffs = useSetting('pveShowSupportBuffs', false)

function effectStatus(e: MaxDmgEffect): { status: EffectStatus, statusText: string } {
    const restriction = effectRestriction(e.detail)
    const only = restriction ? ` (only ${restriction})` : ''
    const enemyCount = maxDmg.value?.enemies.length ?? 0
    // Buff/debuff strength: makes everything this member gives stronger (weaker for DWN_).
    if (isEffectValueType(e.detail.abilityEffectType)) {
        if (excluded.has(e.key)) return { status: 'off', statusText: 'Turned off: click to turn on' }
        const what = e.detail.abilityEffectType.includes('DEBUFF') ? 'debuffs' : 'buffs'
        return { status: 'used', statusText: `${e.detail.abilityEffectType.startsWith('UP') ? 'Strengthens' : 'Weakens'} the ${what} ${e.casterName} gives` }
    }
    if (e.forOwner) {
        if (excluded.has(e.key)) return { status: 'off', statusText: 'Turned off: click to turn on' }
        return { status: 'used', statusText: `On ${e.casterName}: its vortex / DoT damage uses its own ATK and DMG buffs` }
    }
    if (!e.applies) {
        return e.side === 'ally'
            ? { status: 'na', statusText: `Only affects ${e.casterName} itself` }
            : { status: 'na', statusText: `A drawback on ${e.casterName} itself, not on enemies` }
    }
    const allyChosen = e.allyGroup ? allyTargets[e.allyGroup] : undefined
    if (allyChosen && excluded.has(e.key)) return { status: 'off', statusText: 'Turned off: click to turn on' }
    if (allyChosen) {
        if (!allyChosen.length) return { status: 'off', statusText: 'Off on every ally: pick allies below, or click to give it to the dealer' }
        const names = allyChosen.map(i => maxDmg.value?.members[i]?.name).filter(Boolean)
        return { status: 'used', statusText: `On ${names.join(', ')}` }
    }
    const chosen = vortexEnemies[e.key]
    if (chosen && !chosen.length) return { status: 'off', statusText: 'Off on every enemy: pick enemies below, or click to put it on all' }
    if (!chosen && excluded.has(e.key)) return { status: 'off', statusText: 'Turned off: click to turn on' }
    if (!chosen && e.defaultOff && !included.has(e.key)) return {
        status: 'off', statusText: `Off by default: a vortex counts from one skill only (the dealer's Battle Skill, another member's Ultimate). Click to turn on`,
    }
    if (e.tierUsed) return {
        status: 'alt', statusText: e.tier?.reason === 'alternative'
            ? 'Same kind of effect from a skill that stands in for another (switch skill / other follow-up): only the strongest counts'
            : 'Only one tier is active at a time (its conditions exclude each other)',
    }
    if (!e.reach) return { status: 'off', statusText: 'Set to 0 stacks' }
    if (e.side === 'ally') {
        return e.reach.dealer
            ? { status: 'used', statusText: `On ${dealerName.value}` }
            : { status: 'na', statusText: `Only for ${restriction || 'other'} allies: ${dealerName.value} isn't one` }
    }
    const hit = e.reach.enemies.length
    if (!hit) return { status: 'na', statusText: `No enemy in this wave can receive it${only}` }
    return hit < enemyCount
        ? { status: 'partial', statusText: `On ${hit} of ${enemyCount} enemies${only}` }
        : { status: 'used', statusText: enemyCount === 1 ? 'On the enemy' : `On all ${enemyCount} enemies` }
}

const effectRows = computed(() => (maxDmg.value?.effects ?? []).map(e => {
    const count = Math.max(0, Math.min(e.maxStacks, stacks.get(e.key) ?? e.maxStacks))
    return {
        key: e.key, side: e.side, type: e.detail.abilityEffectType, name: effectName(e.detail.abilityEffectType),
        // Team slot (0-4) of the caster: the column its card goes in.
        slot: filledSlots.value[e.casterPos]?.[1] ?? e.casterPos, casterName: e.casterName, source: e.source, maxStacks: e.maxStacks, stacks: count,
        // Shown as given: after the caster's buff/debuff strength (e.rate).
        value: effectValue(e.rate && e.rate !== 1 ? { ...e.detail, value1: e.detail.value1 * e.rate } : e.detail, e.maxStacks > 1 ? count : 1),
        rate: e.rate ?? 1,
        tierGroup: e.tier?.group,
        forOwner: !!e.forOwner,
        // vortex: which enemies it is on (enemy chips on its card)
        vortex: e.detail.abilityEffectType === 'VORTEX_ATK',
        onEnemies: vortexEnemies[e.key] ?? e.reach?.enemies ?? [],
        // single-target ally buff: which allies get it (ally chips on its card; the dealer by default)
        // (one choice per skill, on its first such buff: MaxDmgEffect.allyGroup)
        allyPick: !!e.allyGroup && e.allyGroup === e.key && !e.forOwner,
        onAllies: (e.allyGroup ? allyTargets[e.allyGroup] : undefined) ?? e.reach?.allies ?? [],
        description: effectDescription(e.detail),
        blendGroup: e.blendGroup,
        // a card of merged effects (blendGroup) lists every one of these
        keys: [e.key],
        ids: [skillDetailId(e.detail)],
        sources: [e.source],
        startConds: e.detail.startConditionSetIdCsv ? [e.detail.startConditionSetIdCsv] : [] as string[],
        activeConds: e.detail.activeConditionSetIdCsv ? [e.detail.activeConditionSetIdCsv] : [] as string[],
        ...effectStatus(e),
    }
}))
// Effects that feed one state in battle (MaxDmgEffect.blendGroup: one stack counter, e.g. an ATK +2% (max 15 stacks)
// given by several triggers of the ability and the ascension) are one card: the first effect's text and stacks, every
// effect's id, source and conditions, the best status. Toggling or setting stacks on it acts on all of them.
const effectViews = computed(() => {
    const out: (typeof effectRows.value)[number][] = []
    const byGroup = new Map<string, (typeof effectRows.value)[number]>()
    const addUnique = (list: string[], items: string[]) => { for (const x of items) if (!list.includes(x)) list.push(x) }
    for (const row of effectRows.value) {
        const card = row.blendGroup ? byGroup.get(row.blendGroup) : undefined
        if (!card) {
            const v = { ...row, keys: [...row.keys], ids: [...row.ids], sources: [...row.sources], startConds: [...row.startConds], activeConds: [...row.activeConds] }
            if (row.blendGroup) byGroup.set(row.blendGroup, v)
            out.push(v)
            continue
        }
        card.keys.push(row.key)
        card.ids.push(...row.ids)
        addUnique(card.sources, row.sources)
        addUnique(card.startConds, row.startConds)
        addUnique(card.activeConds, row.activeConds)
        if (row.description && !card.description.split('\n').includes(row.description)) card.description = card.description ? `${card.description}\n${row.description}` : row.description
        card.forOwner ||= row.forOwner
        if (STATUS_ORDER[row.status] < STATUS_ORDER[card.status]) { card.status = row.status; card.statusText = row.statusText }
    }
    return out
})
type EffectView = (typeof effectViews.value)[number]

// A card's click: one effect as before; a merged card turns all its effects on or off together.
function toggleCard(e: EffectView) {
    if (e.keys.length === 1) return toggleEffect(e.key)
    const on = e.status === 'off'
    for (const k of e.keys) {
        if (on) { excluded.delete(k); if (isOffByDefault(k)) included.add(k) }
        else { excluded.add(k); included.delete(k) }
    }
}
// Stacks on a merged card: its stack counter gets them from the first effect, the others give none (at the max, all
// give theirs: the counter is capped anyway).
function setCardStacks(e: EffectView, v: number) {
    setStacks(e.key, v, e.maxStacks)
    const n = stacks.get(e.key) ?? e.maxStacks
    for (const k of e.keys.slice(1)) { if (n === e.maxStacks) stacks.delete(k); else stacks.set(k, 0) }
}

function copyId(id: number) {
    const text = String(id)
    navigator.clipboard?.writeText(text).then(() => toast.success(`Copied: ${text}`), () => toast.warning('Could not copy'))
}

const effectCounts = computed(() => {
    const counts = { buff: 0, debuff: 0, off: 0, na: 0, support: 0 }
    for (const e of effectViews.value) {
        if (e.forOwner) {
            if (e.status !== 'off') counts.support++
            else if (showSupportBuffs.value) counts.off++
            continue
        }
        if (e.status === 'off' || e.status === 'na') counts[e.status]++
        else if (e.status !== 'alt') counts[e.side === 'ally' ? 'buff' : 'debuff']++
    }
    return counts
})

const effectSections = computed(() => {
    const bySource = new Map<string, EffectView[]>()
    for (const e of effectViews.value) {
        if (e.status === 'na' && !showUnreachable.value) continue
        if (e.forOwner && !showSupportBuffs.value) continue
        bySource.set(e.source, [...(bySource.get(e.source) ?? []), e])
    }
    const rank = (source: string) => { const i = SOURCE_ORDER.indexOf(source); return i < 0 ? SOURCE_ORDER.length : i }
    return [...bySource].sort(([a], [b]) => rank(a) - rank(b)).map(([source, effects]) => {
        const toggleable = effects.filter(e => e.status !== 'na')
        // the card that picks a skill's single-target targets (allyPick) goes on top of its cell
        const sorted = effects.sort((a, b) => Number(b.allyPick) - Number(a.allyPick) || STATUS_ORDER[a.status] - STATUS_ORDER[b.status] || a.name.localeCompare(b.name))
        // A tier ladder counts as one effect.
        const unit = (e: EffectView) => e.tierGroup ?? e.key
        return {
            source,
            toggleable,
            total: new Set(toggleable.map(unit)).size,
            onCount: new Set(toggleable.filter(e => e.status === 'used' || e.status === 'partial').map(unit)).size,
            // A "Buffs" and a "Debuffs" row, each with one cell per team slot.
            rows: ([['ally', 'Buffs'], ['enemy', 'Debuffs']] as const)
                .map(([side, title]) => ({ side, title, cells: [0, 1, 2, 3, 4].map(i => sorted.filter(e => e.side === side && e.slot === i)) }))
                .filter(row => row.cells.some(c => c.length)),
        }
    })
})

function setSectionOn(effects: EffectView[], on: boolean) {
    for (const k of effects.flatMap(e => e.keys)) {
        if (on) { excluded.delete(k); if (isOffByDefault(k)) included.add(k) }
        else { excluded.add(k); included.delete(k) }
    }
}

// Score Attack score, same estimate as the previous version of this page.
const isScoreAttack = computed(() => !!getScoreAttackStage(stageId.value))
const saDamage = computed(() => dealer.value?.best?.total.crit ?? 0)
const saStageScore = computed(() => scoreAttackStageScore(stageId.value))
const saInputs = computed<ScoreAttackScoreInputs>(() => {
    const st = saStageScore.value
    return { difficultyScore: st ? st.difficultyScore : difficultyScore.value, scoreMultiplier: scoreMultiplier.value, turns: saTurns.value,
        hpPercent: hpPercentTeam.value, coefficient: st?.coefficient ?? 20, roundScale: st?.roundScale ?? 1 }
})
const saScore = computed(() => scoreAttackScoreParts(saDamage.value, saInputs.value).final.toLocaleString())
const saScoreTitle = computed(() => {
    const i = saInputs.value, p = scoreAttackScoreParts(saDamage.value, i)
    return `${i.difficultyScore.toLocaleString()} + ${i.coefficient} × (Max DMG ${p.maxDmg.toLocaleString()} + Clear Rounds ${p.clearRounds.toLocaleString()} + Remaining HP ${p.remainingHp.toLocaleString()})`
})

// ---- battle simulator ----
// shallowRef + markRaw: keep the engine out of Vue reactivity (object identity matters, see PvP page).
const battle = shallowRef<EngineBattle | null>(null)
const battleOutput = ref<BattleSnapshot[]>([])
const battleResult = ref<'win' | 'lose' | undefined>()
const canRun = computed(() => !!teamKiokus.value.length && !!stageId.value)

// RNG (models/BattleRng.ts) and targeting. Auto: the targeting AI picks, and its random picks are
// rolls like any other. Manual: the battle stops at every target decision (either team) until
// you pick; picks and changed rolls are replayed from the start (decisions, by roll index).
const TARGET_MODE_OPTIONS = [
    { value: 'auto', label: 'Auto', title: 'Full auto: allies use Battle Skill whenever there is SP, fire ultimates as soon as they are ready, and targets follow the game\'s targeting rules (AI); where those pick at random, the RNG setting below decides.' },
    { value: 'manual', label: 'Manual', title: 'You play the allies: on each ally turn choose Battle Skill or Basic Attack (or fire a ready ultimate first), choose which ultimates to fire between actions, and pick every target, for both teams. The battle stops at each decision until you choose.' },
] as const
const targetMode = useSetting<'auto' | 'manual'>('pveTargetMode', 'auto')
const rngMode = useSetting<RngMode>('pveRngMode', 'seed')
const seed = ref(Math.floor(Math.random() * 2 ** 32))
const decisions = shallowRef(new Map<number, RngDecision>())
const pending = shallowRef<RngEvent | null>(null)
const pickPanel = ref<HTMLElement | null>(null)
const changedRolls = computed(() => [...decisions.value.values()].filter(d => !d.pick).length)
const pickCount = computed(() => [...decisions.value.values()].filter(d => d.pick).length)
const actionCount = computed(() => battleOutput.value.slice(1).filter(s => !s.wave).length)

// ---- Actions strip: what to press in game, in order ----
// One chip per ally input (ultimate, battle skill, basic attack; a picked target is added), numbered like the
// timeline's actions. Enemy acts, follow-ups and Vanguard entries are left out (nothing to press); rounds and
// waves are markers between the chips.
type ActionStep = { divider?: string, n?: number, text?: string, kind?: string, title?: string }
const shortUnit = (u: string) => u.replace(/ \(Ally \d+\)$/, '').replace(/^.* \(Enemy (\d+)\)$/, '#$1')
const actionSteps = computed<ActionStep[]>(() => {
    const out: ActionStep[] = []
    let n = 0, round = 1
    const divider = (d: string) => {
        if (out.length && out[out.length - 1].divider) out[out.length - 1].divider += ` · ${d}`
        else out.push({ divider: d })
    }
    for (const s of battleOutput.value.slice(1)) {
        if (s.wave) { divider(`Wave ${s.wave}`); continue }
        n++
        if (s.round && s.round !== round) { round = s.round; divider(`R${round}`) }
        if (!s.lastTeamIsTeam1 || !s.lastActor) continue
        const t = s.lastTargetType
        if (t !== TargetType.specialId && t !== TargetType.skillId && t !== TargetType.attackId) continue
        const target = (s.rngEvents ?? []).find(e => e.kind === 'target' && e.label.startsWith(`${s.lastActor} (`))
        const targetText = target ? ` → ${shortUnit(target.options?.[target.outcome as number]?.label ?? '?')}` : ''
        const extra = s.actionLabel && s.actionLabel !== 'Cutaway' ? ` (${s.actionLabel.toLowerCase()})` : ''
        const what = t === TargetType.specialId ? 'Ult' : t === TargetType.skillId ? 'Skill' : 'Basic'
        out.push({
            n, kind: t === TargetType.specialId ? 'ult' : t === TargetType.skillId ? 'skill' : 'basic',
            text: t === TargetType.specialId ? `Ult ${s.lastActor}${targetText}` : `${s.lastActor} ${what}${targetText}${extra}`,
            title: `Action ${n} · round ${s.round ?? round}${s.actionLabel ? ` · ${s.actionLabel}` : ''}`,
        })
    }
    if (out.length && out[out.length - 1].divider) out.pop()
    return out
})
// The decision the battle is waiting for, as the strip's last chip.
const pendingStepText = computed(() => {
    const p = pending.value
    if (!p) return ''
    if (p.label.startsWith('Between')) return 'next: fire an ult?'
    const who = shortUnit(p.label.split(' · ')[0])
    return p.kind === 'target' ? `next: ${who}'s target?` : `next: ${who}?`
})
const actionsRow = ref<HTMLElement | null>(null)
watch(actionSteps, () => nextTick(() => { const el = actionsRow.value; if (el) el.scrollLeft = el.scrollWidth }))
function copyActions() {
    const text = actionSteps.value.map(x => x.divider ? `[${x.divider}]` : `${x.n}. ${x.text}`).join('  ')
    navigator.clipboard?.writeText(text).then(() => toast.success('Actions copied'), () => toast.warning('Could not copy'))
}
const battleResultText = computed(() => pending.value ? 'Waiting for your decision'
    : battleResult.value === 'win' ? 'Cleared'
        : battleResult.value === 'lose' ? (battle.value?.finishedByRoundLimit ? 'Round limit reached' : 'Defeated') : '')

// ---- Solo Raid: party buff, round limit, attempts carrying over (PvEBattle / PvPBattle.raidCarry) ----
const raid = computed(() => stageId.value ? soloRaidInfo(stageId.value) : undefined)
// Link Raid (MultiRaidGameDirector): the boss's HP when you join, empty = full (a fresh raid).
const linkRaid = computed(() => stageId.value ? multiRaidInfo(stageId.value) : undefined)
const linkRaidFullHp = computed(() => linkRaid.value ? EngineBattle.multiRaidBossHp(stageId.value) : 0)
const linkRaidBossHp = ref<number | ''>('')
watch(stageId, () => { linkRaidBossHp.value = '' })
watch(linkRaidBossHp, () => { if (hasRun()) runSimulation(); else buildBattle() })
const linkRaidBonuses = computed(() => (linkRaid.value?.bonusPassiveIds ?? []).map(id => {
    const p = (passiveMstJson as any[]).find(x => x.passiveSkillMstId === id)
    return p ? String(p.description).replace(/<br>/g, ' ') : `#${id}`
}))
// Solo Raid party buff choices: the buffs each gives every ally, and how it earns Vanguard points.
const partyBuffViews = computed(() => (raid.value?.partyBuffs ?? []).map(p => ({
    value: String(p.soloRaidPartyBuffMstId),
    label: passiveInfo(p.passiveSkillMstId).name,
    title: passiveInfo(p.passiveSkillMstId).description,
    buffs: (passiveDetailsByMstId.get(p.passiveSkillMstId) ?? []).map(d =>
        effectDescription(d as unknown as SkillDetail) || `${effectName(d.abilityEffectType)} ${effectValue(d as unknown as SkillDetail) ?? ''}`.trim()),
    charge: (passiveDetailsByMstId.get(p.buffPointChargePassiveSkillMstId) ?? [])
        .map(d => String(d.description ?? '').replace(/grants \d+ Vanguard points?/, 'grants Vanguard points'))[0] ?? '',
})))
const partyBuffOptions = computed(() => partyBuffViews.value.map(({ value, label, title }) => ({ value, label, title })))
const partyBuffChoice = computed<string>({
    get: () => String(partyBuffId.value || raid.value?.partyBuffs[0]?.soloRaidPartyBuffMstId || ''),
    set: v => { partyBuffId.value = Number(v) },
})
const raidAttempts = shallowRef<RaidCarry[]>([])
const crisisTimeline = computed(() => raid.value ? { difficulty: raid.value.difficulty, battleCount: raidAttempts.value.length + 1, avBefore: raidAttempts.value.reduce((t, a) => t + (a.elapsed ?? 0), 0) } : undefined)
const passiveNames = new Map<number, { name: string, description: string }>((passiveMstJson as any[]).map(p => [p.passiveSkillMstId, { name: p.name, description: String(p.description ?? '').replace(/<br>/g, '\n') }]))
const passiveInfo = (id: number) => passiveNames.get(id) ?? { name: `Passive ${id}`, description: '' }

function nextAttempt() {
    const carry = battle.value?.isOver ? battle.value.raidCarry() : undefined
    if (!carry) return
    raidAttempts.value = [...raidAttempts.value, carry]
    decisions.value = new Map()
    seed.value = Math.floor(Math.random() * 2 ** 32)
    runSimulation()
}
function resetAttempts() {
    raidAttempts.value = []
    decisions.value = new Map()
    runSimulation()
}
watch(partyBuffId, () => { if (hasRun()) runSimulation(); else buildBattle() })

// Set for the first run of an imported file: its picks may sit at shifted indices (engine changes since the export).
let relaxedPicksRun = false

function newBattle(): EngineBattle {
    // Fresh units: a battle mutates its units' state. The 1:1 game engine (src/engine) through src/battle/EngineBattle.
    const allies = filledSlots.value.map(([s]) => buildSlotKioku(s))
    const carry = raidAttempts.value[raidAttempts.value.length - 1]
    const opts = {
        seed: seed.value, rngMode: rngMode.value, decisions: decisions.value, relaxedPicks: relaxedPicksRun,
        manualTargeting: targetMode.value === 'manual',
    }
    if (linkRaid.value) {
        const bossHp = linkRaidBossHp.value && linkRaidBossHp.value > 0 ? Math.min(linkRaidBossHp.value, linkRaidFullHp.value) : undefined
        return markRaw(new EngineBattle({ kind: 'multiRaid', allies, stageId: stageId.value, bossHp }, opts))
    }
    return markRaw(isSoloRaidStage(stageId.value)
        ? new EngineBattle({ kind: 'soloRaid', allies, stageId: stageId.value, partyBuffId: partyBuffId.value || undefined, carry }, opts)
        : new EngineBattle({ kind: 'quest', allies, stageId: stageId.value }, opts))
}

// Initial state only (no simulation yet).
function buildBattle() {
    battleResult.value = undefined
    pending.value = null
    if (!canRun.value || !waves.value.length) {
        battle.value = null
        battleOutput.value = []
        return
    }
    try {
        battle.value = newBattle()
        battleOutput.value = [battle.value.initialState]
    } catch (e) {
        console.warn('Could not build battle', e)
        battle.value = null
        battleOutput.value = []
    }
}
watch([() => team.slots, stageId], () => {
    decisions.value = new Map()
    raidAttempts.value = []
    buildBattle()
}, { deep: true, immediate: true })


function runSimulation() {
    if (!canRun.value || !waves.value.length) return buildBattle()
    let b: EngineBattle
    try {
        b = newBattle()
    } catch (e) {
        console.warn('Could not build battle', e)
        return buildBattle()
    }
    battle.value = b
    pending.value = null
    const states: BattleSnapshot[] = [b.initialState]
    for (let t = 0; t < simTurns.value && !b.isOver; t++) {
        try {
            states.push(...b.executeNextAction())
        } catch (e) {
            if (e instanceof PendingDecision) {
                pending.value = e.event
                break
            }
            toast.warning(String(e))
            console.warn('Failed to execute next action:', e)
            break
        }
    }
    battleOutput.value = states
    battleResult.value = pending.value ? undefined : b.result
    if (pending.value) nextTick(() => pickPanel.value?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }))
}

const hasRun = () => battleOutput.value.length > 1 || !!pending.value
watch([rngMode, targetMode], () => { if (hasRun()) runSimulation(); else buildBattle() })

function setSeed(v: number) {
    seed.value = v
    runSimulation()
}

// `branch`: the decision starts a new line from that point, so every later decision (picks and flipped rolls) is
// dropped. Decisions match by roll index + kind + label only, and the same label comes back all the time ("Tiro
// Finale (Ally 1) · turn: choose an action"), so a pick left over from the old line would be replayed in the new one
// as whatever option sits at its index there (e.g. an ultimate you never chose).
function setDecision(index: number, d: RngDecision | undefined, branch = false) {
    const next = new Map(branch ? [...decisions.value].filter(([i]) => i < index) : decisions.value)
    if (d) next.set(index, d); else next.delete(index)
    decisions.value = next
    runSimulation()
}

// Answering the waiting decision: anything stored past it is from an abandoned line (see setDecision).
function pickTarget(i: number) {
    const ev = pending.value
    if (ev) setDecision(ev.index, { kind: ev.kind, label: ev.label, value: i, pick: true }, true)
}

// Changing a pick in the timeline branches (later decisions go); flipping a roll keeps them (labels name the actor
// and target, so a stale flip rarely matches, and re-flipping every later crit after one change would be tedious).
function onDecide(ev: RngEvent, value: boolean | number) {
    if (ev.userPick) return setDecision(ev.index, { kind: ev.kind, label: ev.label, value, pick: true }, true)
    setDecision(ev.index, value === ev.defaultOutcome ? undefined : { kind: ev.kind, label: ev.label, value })
}

// The last pick the current run actually used, read from the battle's own roll record (it includes the rolls of
// an action cut short by the waiting decision, which no snapshot shows yet).
const lastUsedPick = computed(() => {
    const evs = battle.value?.rng.events ?? []
    for (let k = evs.length - 1; k >= 0; k--) if (evs[k].userPick) return evs[k]
    return undefined
})

// Undo: forget the last pick and everything after it; the battle re-runs and asks that question again.
function undoLastPick() {
    const ev = lastUsedPick.value
    if (!ev) return
    decisions.value = new Map([...decisions.value].filter(([i]) => i < ev.index))
    runSimulation()
}

function resetRolls() {
    decisions.value = new Map([...decisions.value].filter(([, d]) => d.pick))
    if (hasRun()) runSimulation(); else buildBattle()
}

function resetPicks() {
    decisions.value = new Map([...decisions.value].filter(([, d]) => !d.pick))
    runSimulation()
}

// ---- export / import (utils/pvpExport.ts: buildPvEExport / parsePvEExport) ----
const importInput = ref<HTMLInputElement | null>(null)

function exportBattle() {
    if (!canRun.value) return
    if (!hasRun()) runSimulation()
    const data = buildPvEExport({
        stageId: stageId.value, stageName: questStages.get(stageId.value)?.name,
        control: targetMode.value, rngMode: rngMode.value, seed: seed.value, turns: simTurns.value,
        decisions: decisions.value, slots: team.slots, snapshots: battleOutput.value, pending: pending.value,
        soloRaid: raid.value ? { partyBuffId: partyBuffId.value || undefined, attempts: raidAttempts.value } : undefined,
    })
    const tag = rngMode.value === 'seed' ? `seed${seed.value}` : rngMode.value
    downloadText(`pve-sim-${stageId.value}-${targetMode.value}-${tag}.json`, exportToText(data))
    toast.success(`Exported the run${data.decisionLog.length ? ` with ${data.decisionLog.length} decision${data.decisionLog.length === 1 ? '' : 's'}` : ''}`)
}

async function importBattle(ev: Event) {
    const input = ev.target as HTMLInputElement
    const file = input.files?.[0]
    input.value = ''
    if (!file) return
    try {
        const data = parsePvEExport(await file.text())
        await applyPvEExport(data)
        toast.success(`Imported ${data.stageName ?? `stage ${data.stageId}`} (${data.control} control, ${data.rngMode} RNG)`)
    } catch (e) {
        toast.error(`Could not import: ${(e as Error).message}`)
    }
}

// Puts an export's stage, team, settings and decisions on the page and runs it (Import file).
async function applyPvEExport(data: PvEExport) {
    if (!stageWaves(data.stageId).length) throw new Error(`stage ${data.stageId} is not in this build's data`)
    saved.detach() // an imported file is a new setup, not an edit of the selected saved team
    stageId.value = data.stageId
    team.importSlots(data.slots)
    await nextTick() // lets the team/stage watcher reset its state first
    seed.value = data.seed
    simTurns.value = data.turns
    rngMode.value = data.rngMode ?? 'seed'
    targetMode.value = data.control ?? 'auto'
    decisions.value = new Map(Object.entries(data.decisions ?? {}).map(([k, v]) => [Number(k), v]))
    if (data.soloRaid) {
        partyBuffId.value = data.soloRaid.partyBuffId ?? 0
        raidAttempts.value = data.soloRaid.attempts ?? []
    }
    await nextTick() // the mode watchers re-run first; run once more with everything in place
    // Picks are matched by label where an engine change shifted their indices, then stored at the indices they
    // were used at (BattleRng relaxedPicks / rekeyPicks).
    relaxedPicksRun = true
    try { runSimulation() } finally { relaxedPicksRun = false }
    decisions.value = rekeyPicks(decisions.value, battleOutput.value)
}

// "Name (Enemy 2)" -> that unit's HP in the latest state, for the pick buttons.
function hpOf(label: string): string {
    const m = /\((Ally|Enemy) (\d+)\)$/.exec(label)
    const last = battleOutput.value[battleOutput.value.length - 1]
    if (!m || !last) return ''
    const u = (m[1] === 'Ally' ? last.allies : last.enemies).team[Number(m[2]) - 1]
    return u ? `HP ${fmt(u.hp)} / ${fmt(u.maxHp)}` : ''
}

// ---- saved teams: the team plus this page's whole setup (utils/pveSetup.ts) ----
function currentSetup(): PvESetup {
    return {
        stageId: stageId.value,
        wave: waveIdx.value,
        phase: phase.value,
        target: mainTargetIdx.value,
        broken: [...broken.value],
        breakRate: breakRate.value.map(r => r ?? null),
        dead: alive.value.map((a, i) => a ? -1 : i).filter(i => i >= 0),
        dealer: attackerIndex.value,
        excluded: [...excluded],
        included: [...included],
        vortexEnemies: JSON.parse(JSON.stringify(vortexEnemies)),
        allyTargets: JSON.parse(JSON.stringify(allyTargets)),
        stacks: Object.fromEntries(stacks),
        control: targetMode.value,
        rngMode: rngMode.value,
        seed: seed.value,
        turns: simTurns.value,
        decisions: [...decisions.value],
        ran: hasRun(),
        raid: raid.value ? { partyBuffId: partyBuffId.value, noRoundLimit: false, attempts: raidAttempts.value } : null,
    }
}

// Called right after the team's slots were loaded. Staged like importBattle: the stage and team watchers
// reset the wave, target, decisions and attempts first, then the saved values go in.
async function applySetup(raw: unknown) {
    if (!raw) return
    const s = sanitizePvESetup(raw)
    if (!stageWaves(s.stageId).length) {
        toast.warning(`This team's stage (${s.stageId}) isn't in this version's data, so only the team was loaded.`)
        return
    }
    stageId.value = s.stageId
    attackerIndex.value = s.dealer
    await nextTick()
    waveIdx.value = Math.min(s.wave, Math.max(0, waves.value.length - 1))
    await nextTick()
    if (phases.value.some(f => f.step === s.phase)) phase.value = s.phase!
    await nextTick()
    if (s.dead.length && s.dead.length < wave.value.length && s.dead.every(i => i < wave.value.length)) alive.value = wave.value.map((_, i) => !s.dead.includes(i))
    if (s.target < wave.value.length) mainTargetIdx.value = s.target
    if (s.broken.length === wave.value.length) broken.value = [...s.broken]
    if (s.breakRate.length === wave.value.length) breakRate.value = s.breakRate.map(r => r ?? undefined)
    resetEffects()
    s.excluded.forEach(k => excluded.add(k))
    s.included?.forEach(k => included.add(k))
    Object.entries(s.vortexEnemies ?? {}).forEach(([k, v]) => { vortexEnemies[k] = [...v] })
    Object.entries(s.allyTargets ?? {}).forEach(([k, v]) => { allyTargets[k] = [...v] })
    Object.entries(s.stacks).forEach(([k, v]) => stacks.set(k, v))
    seed.value = s.seed
    simTurns.value = s.turns
    rngMode.value = s.rngMode
    targetMode.value = s.control
    if (s.raid) {
        partyBuffId.value = s.raid.partyBuffId
        raidAttempts.value = s.raid.attempts
    }
    decisions.value = new Map(s.decisions)
    await nextTick() // the mode / raid watchers re-run first
    if (s.ran || s.decisions.length) runSimulation(); else buildBattle()
}

const shareCardRef = ref<HTMLElement | null>(null)
const exportOpts = { exportClass: 'exporting' }

const runSummary = computed(() => [
    targetMode.value === 'manual' ? 'Manual control' : 'Auto control',
    rngMode.value === 'seed' ? `seed ${seed.value}` : `${rngMode.value} RNG`,
    pickCount.value ? `${pickCount.value} decision${pickCount.value === 1 ? '' : 's'}` : '',
    changedRolls.value ? `${changedRolls.value} changed roll${changedRolls.value === 1 ? '' : 's'}` : '',
].filter(Boolean).join(' · '))

const saved = useSavedTeams({
    kind: 'pve',
    routePath: '/pve-simulator',
    label: 'PvE Team',
    getSlots: () => [team.slots],
    applySlots: slots => team.importSlots(slots[0]),
    shareTarget: () => shareCardRef.value!,
    exportOptions: exportOpts,
    extra: {
        get: currentSetup,
        sanitize: sanitizePvESetup,
        apply: applySetup,
        describe: describePvESetup,
    },
    saveHint: 'The team, stage, settings and every decision are saved to this team automatically.',
})
</script>

